"""
    Parse the GFF attribute column and return a dict
    """
def odict_to_attributes_gff(attributes: Any) -> object {
    if attributes {
        atts = [];
        for (k, v) in attributes.items() {
            atts.append('{}={}'.format(k, v));
        }
        temp_atts = ";".join(atts);
        return temp_atts.rstrip();
    }
    return '.';
}

